class PdfToEmfConverterFactory_CreateConverter_ProxyToResponder : public ::mojo::internal::ProxyToResponder {
 public:
  static PdfToEmfConverterFactory::CreateConverterCallback CreateCallback(
      ::mojo::Message& message,
      std::unique_ptr<mojo::internal::ResponderThunk>&& responder) {
    std::unique_ptr<PdfToEmfConverterFactory_CreateConverter_ProxyToResponder> proxy(
        new PdfToEmfConverterFactory_CreateConverter_ProxyToResponder(
            message, std::move(responder)));
    return base::BindOnce(&PdfToEmfConverterFactory_CreateConverter_ProxyToResponder::Run,
                          std::move(proxy));
  }

  ~PdfToEmfConverterFactory_CreateConverter_ProxyToResponder() {
#if DCHECK_IS_ON()
    if (responder_) {
      // If we're being destroyed without being run, we want to ensure the
      // binding endpoint has been closed. This checks for that asynchronously.
      // We pass a bound generated callback to handle the response so that any
      // resulting DCHECK stack will have useful interface type information.
      // Instantiate a ScopedFizzleBlockShutdownTasks to allow this request to
      // fizzle if this happens after shutdown and the endpoint is bound to a
      // BLOCK_SHUTDOWN sequence.
      base::ThreadPoolInstance::ScopedFizzleBlockShutdownTasks fizzler;
      responder_->IsConnectedAsync(base::BindOnce(&OnIsConnectedComplete));
    }
#endif
  }

 private:
  PdfToEmfConverterFactory_CreateConverter_ProxyToResponder(
      ::mojo::Message& message,
      std::unique_ptr<mojo::internal::ResponderThunk>&& responder)
      : ::mojo::internal::ProxyToResponder(message, std::move(responder)) {
  }

#if DCHECK_IS_ON()
  static void OnIsConnectedComplete(bool connected) {
    DCHECK(!connected)
        << "PdfToEmfConverterFactory::CreateConverterCallback was destroyed without "
        << "first either being run or its corresponding binding being closed. "
        << "It is an error to drop response callbacks which still correspond "
        << "to an open interface pipe.";
  }
#endif

  void Run(
      ::mojo::PendingRemote<PdfToEmfConverter> in_converter, uint32_t in_page_count);
};

bool PdfToEmfConverterFactory_CreateConverter_ForwardToCallback::Accept(
    mojo::Message* message) {
  DCHECK(message->is_serialized());
  internal::PdfToEmfConverterFactory_CreateConverter_ResponseParams_Data* params =
      reinterpret_cast<
          internal::PdfToEmfConverterFactory_CreateConverter_ResponseParams_Data*>(
              message->mutable_payload());
  

  // Validation for PdfToEmfConverterFactory.0
  bool success = true;
  ::mojo::PendingRemote<PdfToEmfConverter> p_converter{};
  uint32_t p_page_count{};
  PdfToEmfConverterFactory_CreateConverter_ResponseParamsDataView input_data_view(params, message);
  
  if (success) {
    p_converter =
        input_data_view.TakeConverter<decltype(p_converter)>();
  }
  if (success)
    p_page_count = input_data_view.page_count();
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        PdfToEmfConverterFactory::Name_, 0, true);
    return false;
  }
  if (!callback_.is_null()) {
    std::move(callback_).Run(
std::move(p_converter), 
std::move(p_page_count));
  }
  return true;
}

void PdfToEmfConverterFactory_CreateConverter_ProxyToResponder::Run(
    ::mojo::PendingRemote<PdfToEmfConverter> in_converter, uint32_t in_page_count) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send reply printing::mojom::PdfToEmfConverterFactory::CreateConverter", "async_response_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("converter"), in_converter,
                        "<value of type ::mojo::PendingRemote<PdfToEmfConverter>>");
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("page_count"), in_page_count,
                        "<value of type uint32_t>");
   });
#endif

  const uint32_t kFlags = mojo::Message::kFlagIsResponse |
      ((is_sync_) ? mojo::Message::kFlagIsSync : 0) |
      ((true) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((false) ? mojo::Message::kFlagIsUrgent : 0);

  const size_t estimated_payload_size =
    0;
  mojo::Message message(
      std::to_underlying(messages::PdfToEmfConverterFactory::kCreateConverter), kFlags, estimated_payload_size);
  mojo::internal::MessageFragment<
      ::printing::mojom::internal::PdfToEmfConverterFactory_CreateConverter_ResponseParams_Data> params(
          message);
  params.Allocate();

  
  mojo::internal::Serialize<mojo::InterfacePtrDataView<::printing::mojom::PdfToEmfConverterInterfaceBase>>(
    in_converter,
    &params->converter,
    &params.message());

  
  MOJO_INTERNAL_CHECK_SERIALIZATION(
    mojo::internal::SendValidation::kDefault,
    !(!mojo::internal::IsHandleOrInterfaceValid(params->converter)),
    mojo::internal::VALIDATION_ERROR_UNEXPECTED_INVALID_HANDLE,
    "invalid converter in ");

  params->page_count = in_page_count;

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(PdfToEmfConverterFactory::Name_);
  message.set_method_name("CreateConverter");
#endif

  message.set_request_id(request_id_);
  message.set_trace_nonce(trace_nonce_);
  ::mojo::internal::SendMojoMessage(*responder_, message);
  // SendMojoMessage() fails silently if the responder connection is closed,
  // or if the message is malformed.
  //
  // TODO(darin): If Accept() returns false due to a malformed message, that
  // may be good reason to close the connection. However, we don't have a
  // way to do that from here. We should add a way.
  responder_ = nullptr;
}

